<?php
$printableEmployees = array_values(array_filter($employees, function ($employee) { return $employee['status'] === 'activo'; }));
if (count($printableEmployees) === 1) {
    $documentTitle = 'Carnet_' . trim($printableEmployees[0]['first_name'] . '_' . $printableEmployees[0]['last_name']);
} elseif (count($printableEmployees) > 1) {
    $firstStudent = trim($printableEmployees[0]['first_name'] . '_' . $printableEmployees[0]['last_name']);
    $documentTitle = 'Carnets_' . $firstStudent . '_y_' . (count($printableEmployees) - 1) . '_mas';
} else {
    $documentTitle = 'Carnets_estudiantiles';
}
$documentTitle = preg_replace('/[^\p{L}\p{N}_-]+/u', '_', $documentTitle);
?>
